123	bool ParseNtsEvent(const std::string &rawEvent, uint64_t &eventValue)
124	{
125	    std::string event = Utils::Trim(rawEvent);
126	    if (event.empty()) {
127	        return false;
128	    }
129	    int32_t base = DECIMAL_BASE;
130	    size_t start = 0;
131	    if (event.size() > HEX_PREFIX_LEN && event[0] == '0' && (event[1] == 'x' || event[1] == 'X')) {
132	        base = HEX_BASE;
133	        start = HEX_PREFIX_LEN;
134	        if (event.size() == start) {
135	            return false;
136	        }
137	    }
138	    for (size_t i = start; i < event.size(); ++i) {
139	        const auto ch = static_cast<unsigned char>(event[i]);
140	        if ((base == HEX_BASE && std::isxdigit(ch) == 0) || (base == DECIMAL_BASE && std::isdigit(ch) == 0)) {
141	            return false;
142	        }
143	    }
144	    size_t pos = 0;
145	    try {
146	        eventValue = std::stoull(event, &pos, base);
147	    } catch (const std::invalid_argument &) {
148	        return false;
149	    } catch (const std::out_of_range &) {
150	        return false;
151	    }
152	    return pos == event.size();
153	}
