408	int32_t InputParser::CheckArgOnOff(const struct MsprofCmdInfo &cmdInfo, int32_t opt) const
409	{
410	    if (CheckOptionValueNotNull(cmdInfo, opt) != MSPROF_DAEMON_OK) {
411	        return MSPROF_DAEMON_ERROR;
412	    }
413	    if (opt == ARGS_MSTX_DOMAIN_INCLUDE || opt == ARGS_MSTX_DOMAIN_EXCLUDE) {
414	        return MSPROF_DAEMON_OK;
415	    }
416	    std::string switchStr = std::string(cmdInfo.args[opt]);
417	    switch (opt) {
418	        case ARGS_GE_API: {
419	            const std::vector<std::string> cmpCode = {OFF, L0, L1};
420	            const std::string errorMsg = "Argument --%s: invalid value: %s. Please input 'off', 'l0' or 'l1'.";
421	            return compareSwitchStr(cmpCode, switchStr, errorMsg, opt, cmdInfo);
422	        }
423	        case ARGS_TASK_BLOCK: {
424	            return CheckTaskBlockValid("--task-block", switchStr);
425	        }
426	        case ARGS_TASK_TIME: {
427	            const bool supportL3 = Platform::instance()->CheckIfSupport(PLATFORM_TASK_TRACE_L3);
428	            const std::vector<std::string> cmpCode = {OFF, L0, L2, L3, L1, ON};
429	            std::string msgEnd = supportL3 ? ", 'l2' or 'l3'" : " or 'l2'.";
430	            std::string errorMsg = "Argument --%s: invalid value: %s. Please input 'on', 'off', 'l0', 'l1'" + msgEnd;
431	
432	            if (compareSwitchStr(cmpCode, switchStr, errorMsg, opt, cmdInfo) != MSPROF_DAEMON_OK) {
433	                return MSPROF_DAEMON_ERROR;
434	            }
435	            if (switchStr.compare(L3) == 0 && !supportL3) {
436	                CmdLog::CmdErrorLog("l3 is not supported on this platform.");
437	                return MSPROF_DAEMON_ERROR;
438	            }
439	            return MSPROF_DAEMON_OK;
440	        }
441	        case ARGS_DVPP_PROFILING: {
442	            if (!Platform::instance()->CheckIfSupport(PLATFORM_SYS_DEVICE_DVPP) &&
443	                !Platform::instance()->CheckIfSupport(PLATFORM_SYS_DEVICE_DVPP_EX)) {
444	                CmdLog::CmdWarningLog("The argument: dvpp-profiling is useless on this platform.");
445	                return MSPROF_DAEMON_OK;
446	            }
447	            const std::vector<std::string> cmpCode = {OFF, ON};
448	            const std::string errorMsg = "Argument --%s: invalid value: %s. Please input 'on' or 'off'.";
449	            return compareSwitchStr(cmpCode, switchStr, errorMsg, opt, cmdInfo);
450	        }
451	        default: {
452	            const std::vector<std::string> cmpCode = {OFF, ON};
453	            const std::string errorMsg = "Argument --%s: invalid value: %s. Please input 'on' or 'off'.";
454	            return compareSwitchStr(cmpCode, switchStr, errorMsg, opt, cmdInfo);
455	        }
456	    }
457	}
