478	int32_t InputParser::CheckNpuEventsValid(const struct MsprofCmdInfo &cmdInfo, int32_t opt) const
479	{
480	    if (CheckOptionValueNotNull(cmdInfo, opt) != MSPROF_DAEMON_OK) {
481	        return MSPROF_DAEMON_ERROR;
482	    }
483	    params_->npuEvents = cmdInfo.args[opt];
484	    if (!Platform::instance()->CheckIfSupport(PLATFORM_TASK_L2_CACHE_REG) &&
485	        !Platform::instance()->CheckIfSupport(PLATFORM_TASK_SOC_PMU)) {
486	        MSPROF_LOGE("Soc pmu not support on this platform.");
487	        return MSPROF_DAEMON_ERROR;
488	    }
489	    static std::string singleEventsHead = "0x";
490	    if (params_->npuEvents.compare(0, singleEventsHead.length(), singleEventsHead) == 0 &&
491	        params_->npuEvents.find(";") != std::string::npos) {
492	        MSPROF_LOGE("Failed to check soc pmu events, if you want to collect multiple soc pmu type, "
493	            "please input prefix like [HA:] before events.");
494	        CmdLog::CmdErrorLog("Failed to check soc pmu events, if you want to collect multiple soc pmu type, "
495	            "please input prefix like [HA:] before events.");
496	        return MSPROF_DAEMON_ERROR;
497	    }
498	    if (!ParamValidation::instance()->CheckDuplicateSocPmu(params_->npuEvents)) {
499	        MSPROF_LOGE("Failed to check soc pmu events, please check if input duplicate soc pmu type.");
500	        CmdLog::CmdErrorLog("Failed to check soc pmu events, please check if input duplicate soc pmu type.");
501	        return MSPROF_DAEMON_ERROR;
502	    }
503	    std::vector<std::string> registerList = Utils::Split(params_->npuEvents, false, "", ";");
504	    for (size_t i = 0; i < registerList.size(); ++i) {
505	        std::string eventStr = "";
506	        ProfSocPmuType eventType = ParamValidation::instance()->GetSocPmuInfo(registerList[i], eventStr);
507	        if (eventStr.empty()) {
508	            MSPROF_LOGE("Failed to check empty soc pmu events, type: %u.", static_cast<uint32_t>(eventType));
509	            CmdLog::CmdErrorLog("Empty npu-events detected, please input valid npu-events.");
510	            return MSPROF_DAEMON_ERROR;
511	        }
512	        std::vector<std::string> eventsList = Utils::Split(eventStr, false, "", ",");
513	        if (!ParamValidation::instance()->CheckSocPmuEventsValid(eventType, eventsList)) {
514	            MSPROF_LOGE("Failed to check soc pmu events, type: %u, event: %s", static_cast<uint32_t>(eventType),
515	                registerList[i].c_str());
516	            CmdLog::CmdErrorLog("The npu-events[%s] is invalid or exceeds the specified length, "
517	                "please check ERROR information in host plog.", params_->npuEvents.c_str());
518	            return MSPROF_DAEMON_ERROR;
519	        }
520	    }
521	
522	    return MSPROF_DAEMON_OK;
523	}
