530	    }
531	    switch (opt) {
532	        case ARGS_OUTPUT:
533	            break;
534	        case ARGS_STORAGE_LIMIT:
535	            ret = CheckStorageLimitValid(cmdInfo);
536	            break;
537	        case ARGS_APPLICATION:
