539	            break;
540	        case ARGS_ENVIRONMENT:
541	            ret = CheckEnvironmentValid(cmdInfo);
542	            break;
543	        case ARGS_AIC_MODE:
544	        case ARGS_AIV_MODE:
545	            ret = CheckSampleModeValid(cmdInfo, opt);
546	            break;
547	        case ARGS_AIC_METRICS:
