737	SHARED_PTR_ALIA<analysis::dvvp::message::ProfileParams> InputParser::MsprofGetOpts(int32_t argc, CONST_CHAR_PTR argv[])
738	{
739	    if (!Utils::CheckInputArgsLength(argc, argv)) {
740	        return nullptr;
741	    }
742	
743	    int32_t argCount = 1;       // argv[0] is msprof
744	    SplitApplicationArgv(argc, argv, argCount);
745	
746	    int32_t opt = 0;
747	    int32_t optionIndex = 0;
748	    bool setOutput = false;
749	    MsprofString optString = "";
750	    struct MsprofCmdInfo cmdInfo = { {nullptr} };
751	    while ((opt = OsalGetOptLong(argCount, const_cast<MsprofStrBufAddrT>(argv),
752	        optString, LONG_OPTIONS, &optionIndex)) != MSPROF_DAEMON_ERROR) {
753	        if (opt == ARGS_HELP) {
754	            params_->usedParams.clear();
755	            params_->usedParams.insert(opt);
756	            MsprofCmdUsage("");
757	            return params_;
758	        }
759	        setOutput = (opt == ARGS_OUTPUT) ? true : setOutput;
760	        if (PreCheckPlatform(opt, argv) == PROFILING_FAILED) {
761	            return nullptr;
762	        }
763	        if (ProcessOptions(opt, cmdInfo) != MSPROF_DAEMON_OK) {
764	            return nullptr;
765	        }
766	    }
767	
768	    if (!params_->application.empty()) {
769	        HandleApp();
770	    }
771	
772	    if (CheckDynProfValid(cmdInfo) != MSPROF_DAEMON_OK) {
773	        return nullptr;
774	    }
775	
776	    if (CheckMstxValid() != MSPROF_DAEMON_OK) {
777	        return nullptr;
778	    }
779	
780	    if (setOutput && CheckOutputValid(cmdInfo) != MSPROF_DAEMON_OK) {
781	        return nullptr;
782	    }
783	
784	    return ParamsCheck() == MSPROF_DAEMON_OK ? params_ : nullptr;
785	}
