787	/**
788	 * @brief find msprof command parameter and user parameter splits
789	 * @param [in] argc: argc
790	 * @param [in] argv: argv
791	 * @param [out] argCount: msprof parameter count
792	 */
793	void InputParser::SplitApplicationArgv(int32_t argc, CONST_CHAR_PTR argv[], int32_t &argCount)
794	{
795	    const int32_t argWithSpaceNum = 2;
796	    for (int32_t i = 1; i < argc; i++) {
797	        if (argv[i][0] == '-' && argv[i][1] == '-') {
798	            if (std::strchr(argv[i], '=') != nullptr) {
799	                argCount++;
800	            } else if (i + 1 >= argc || argv[i + 1][0] == '-') {
801	                argCount++;
802	            } else {
803	                argCount += argWithSpaceNum;
804	                i++;
805	            }
806	        } else {
807	            for (;i < argc; i++) {
808	                params_->application.emplace_back(argv[i]);
809	            }
810	            return;
811	        }
812	    }
813	}
