828	int32_t InputParser::ProcessOptions(int32_t opt, struct MsprofCmdInfo &cmdInfo)
829	{
830	    int32_t ret = MSPROF_DAEMON_ERROR;
831	    // opt range validate
832	    if (opt < ARGS_HELP || opt >= NR_ARGS || opt == static_cast<int32_t>(ARGS_INVALID)) {
833	        MsprofCmdUsage("");
834	        return ret;
835	    }
836	
837	    cmdInfo.args[opt] = OsalGetOptArg();
838	    params_->usedParams.insert(opt);
839	
840	    if ((opt >= ARGS_OUTPUT && opt <= ARGS_RULE) || opt == ARGS_NTS_METRICS) {
841	        ret = MsprofCmdCheckValid(cmdInfo, opt);
842	    } else if (opt >= ARGS_ASCENDCL && opt <= ARGS_ANALYZE) {
843	        ret = MsprofSwitchCheckValid(cmdInfo, opt);
844	    } else if (opt >= ARGS_AIC_FREQ && opt <= ARGS_EXPORT_MODEL_ID) {
845	        ret = MsprofFreqCheckValid(cmdInfo, opt);
846	    } else if (opt >= ARGS_HOST_SYS && opt <= ARGS_HOST_SYS_USAGE) {
847	        ret = MsprofHostCheckValid(cmdInfo, opt);
848	    } else {
849	        MsprofCmdUsage("");
850	    }
851	    return ret;
852	}
