854	int32_t InputParser::CheckNtsMetricsValid(const struct MsprofCmdInfo &cmdInfo)
855	{
856	    const std::string ntsMetrics = cmdInfo.args[ARGS_NTS_METRICS] == nullptr ? "" : cmdInfo.args[ARGS_NTS_METRICS];
857	    if (ConfigManager::instance()->GetPlatformType() != PlatformType::CHIP_MDC_V2) {
858	        CmdLog::CmdErrorLog("Argument --nts-metrics %s is not supported on current platform.", ntsMetrics.c_str());
859	        return MSPROF_DAEMON_ERROR;
860	    }
861	
862	    if (ntsMetrics.empty()) {
863	        CmdLog::CmdErrorLog("Argument --nts-metrics is empty. Please input in the range of PipeUtilization or "
864	            "Custom:<event-list>.");
865	        return MSPROF_DAEMON_ERROR;
866	    }
867	    if (ntsMetrics == NTS_PIPE_UTILIZATION) {
868	        params_->ntsMetrics = ntsMetrics;
869	        // PipeUtilization is expanded to platform-specific PMU events in RunningMode.
870	        params_->ntsPmuEvents.clear();
871	        return MSPROF_DAEMON_OK;
872	    }
873	    if (ntsMetrics.compare(0, NTS_CUSTOM_PREFIX.size(), NTS_CUSTOM_PREFIX) != 0) {
874	        CmdLog::CmdErrorLog("Argument --nts-metrics: invalid value:%s. Only PipeUtilization or Custom:<event-list> "
875	            "is supported.", ntsMetrics.c_str());
876	        return MSPROF_DAEMON_ERROR;
877	    }
878	    return CheckNtsCustomMetricsValid(ntsMetrics);
879	}
