881	int32_t InputParser::CheckNtsCustomMetricsValid(const std::string &ntsMetrics)
882	{
883	    const std::string eventList = ntsMetrics.substr(NTS_CUSTOM_PREFIX.size());
884	    if (eventList.empty()) {
885	        CmdLog::CmdErrorLog("Argument --nts-metrics: invalid value:%s. Custom event list is empty.",
886	            ntsMetrics.c_str());
887	        return MSPROF_DAEMON_ERROR;
888	    }
889	    std::vector<std::string> events = Utils::Split(eventList, false, "", ",");
890	    if (events.size() > NTS_EVENT_MAX_NUM) {
891	        CmdLog::CmdErrorLog("Argument --nts-metrics: invalid value:%s. The number of custom events should be in "
892	            "the range of [1, 10].", ntsMetrics.c_str());
893	        return MSPROF_DAEMON_ERROR;
894	    }
895	
896	    std::vector<std::string> normalizedEvents;
897	    for (const auto &event : events) {
898	        uint64_t eventValue = 0;
899	        const std::string trimmedEvent = Utils::Trim(event);
900	        if (!ParseNtsEvent(trimmedEvent, eventValue)) {
901	            CmdLog::CmdErrorLog("Argument --nts-metrics: invalid value:%s. Hexadecimal or decimal parameters are "
902	                "allowed in custom mode.", trimmedEvent.c_str());
903	            return MSPROF_DAEMON_ERROR;
904	        }
905	        if (eventValue < NTS_EVENT_MIN || eventValue > NTS_EVENT_MAX) {
906	            CmdLog::CmdErrorLog("Argument --nts-metrics: invalid value:%s. The event is out of range [0x0, 0x71b].",
907	                trimmedEvent.c_str());
908	            return MSPROF_DAEMON_ERROR;
909	        }
910	        normalizedEvents.emplace_back(FormatNtsEvent(eventValue));
911	    }
912	
913	    params_->ntsMetrics = ntsMetrics;
914	    // Custom events are validated and normalized during command parsing.
915	    params_->ntsPmuEvents = JoinNtsEvents(normalizedEvents);
916	    return MSPROF_DAEMON_OK;
917	}
