919	int32_t InputParser::ParamsCheck() const
920	{
921	    if (params_ == nullptr) {
922	        return MSPROF_DAEMON_ERROR;
923	    }
924	
925	    if (Platform::instance()->CheckIfSupport(PLATFORM_TASK_SCALE) &&
926	        params_->taskBlock == "on" &&
927	        params_->taskBlockShink == "off" &&
928	        params_->opType.empty()) {
929	        CmdLog::CmdErrorLog("Argument --task-block: when set to 'all', --optype must not be empty.");
930	        return MSPROF_DAEMON_ERROR;
931	    }
932	
933	    if (!params_->result_dir.empty()) {
934	        return MSPROF_DAEMON_OK;
935	    }
936	    std::string ascendWorkPath;
937	    MSPROF_GET_ENV(MM_ENV_ASCEND_WORK_PATH, ascendWorkPath);
938	    if (!ascendWorkPath.empty()) {
939	        std::string path = Utils::RelativePathToAbsolutePath(ascendWorkPath) + MSVP_SLASH + PROFILING_RESULT_PATH;
940	        if (Utils::CreateDir(path) != PROFILING_SUCCESS) {
941	            char errBuf[MAX_ERR_STRING_LEN + 1] = {0};
942	            CmdLog::CmdErrorLog("Create output dir failed.ErrorCode: %d, ErrorInfo: %s.", OsalGetErrorCode(),
943	                OsalGetErrorFormatMessage(OsalGetErrorCode(), errBuf, MAX_ERR_STRING_LEN));
944	            return MSPROF_DAEMON_ERROR;
945	        }
946	        if (!Utils::IsDirAccessible(path)) {
947	            CmdLog::CmdErrorLog("Profiling output path %s is not a dir or can not accessible.", path.c_str());
948	            return MSPROF_DAEMON_ERROR;
949	        }
950	        params_->result_dir = Utils::CanonicalizePath(path);
951	        if (params_->result_dir.empty()) {
952	            CmdLog::CmdErrorLog("Profiling output path is invalid because of"
953	                                " get the canonicalized absolute pathname failed");
954	            return MSPROF_DAEMON_ERROR;
955	        }
956	    } else {
957	        if (!params_->application.empty()) {
958	            // new cmd save result in current dir when output not set
959	            params_->result_dir = Utils::CanonicalizePath("./");
960	            return MSPROF_DAEMON_OK;
961	        }
962	        if (!params_->app_dir.empty()) {
963	            params_->result_dir = params_->app_dir;
964	        } else {
965	            params_->result_dir = Utils::CanonicalizePath("./");
966	        }
967	    }
968	
969	    return MSPROF_DAEMON_OK;
970	}
