1137	int32_t InputParser::CheckHostSysToolsIsExist(const std::string toolName, const std::string exeCmd) const
1138	{
1139	    std::string tmpDir = analysis::dvvp::common::utils::Utils::IdeGetHomedir();
1140	    static const std::string ENV_PATH = "PATH=/usr/bin/:/usr/sbin:/var";
1141	    std::vector<std::string> envV;
1142	    envV.push_back(ENV_PATH);
1143	    std::vector<std::string> argsV;
1144	    if (exeCmd.compare(PROF_SCRIPT_PROF) == 0) {
1145	        argsV.push_back(PROF_SCRIPT_PROF);
1146	        argsV.push_back("--version");
1147	    } else {
1148	        argsV.push_back(exeCmd);
1149	        argsV.push_back("get-version");
1150	        argsV.push_back(toolName);
1151	    }
1152	    unsigned long long startRealtime = analysis::dvvp::common::utils::Utils::GetClockRealtime();
1153	    tmpDir += "/tmpPrint" + std::to_string(startRealtime);
1154	    int32_t exitCode = analysis::dvvp::common::utils::INVALID_EXIT_CODE;
1155	    static const std::string CMD = "sudo";
1156	    OsalProcess tmpProcess = MSVP_PROCESS;
1157	    ExecCmdParams execCmdParams(CMD, true, tmpDir);
1158	    int32_t ret = analysis::dvvp::common::utils::Utils::ExecCmd(execCmdParams,
1159	                                                            argsV,
1160	                                                            envV,
1161	                                                            exitCode,
1162	                                                            tmpProcess);
1163	    FUNRET_CHECK_FAIL_PRINT(ret != PROFILING_SUCCESS);
1164	    ret = CheckHostSysCmdOutIsExist(tmpDir, toolName, tmpProcess);
1165	    return ret;
1166	}
