1168	int32_t InputParser::CheckHostSysCmdOutIsExist(const std::string tmpDir, const std::string toolName,
1169	                                           const OsalProcess tmpProcess) const
1170	{
1171	    MSPROF_LOGI("Start to check whether the file exists.");
1172	    for (int32_t i = 0; i < FILE_FIND_REPLAY; i++) {
1173	        if (!(Utils::IsFileExist(tmpDir))) {
1174	            OsalSleep(20); // If the file is not found, the delay is 20 ms.
1175	            continue;
1176	        } else {
1177	            break;
1178	        }
1179	    }
1180	    for (int32_t i = 0; i < FILE_FIND_REPLAY; i++) {
1181	        int64_t len = analysis::dvvp::common::utils::Utils::GetFileSize(tmpDir);
1182	        if (len < static_cast<int64_t>(toolName.length())) {
1183	            OsalSleep(5); // If the file has no content, the delay is 5 ms.
1184	            continue;
1185	        } else {
1186	            break;
1187	        }
1188	    }
1189	    std::string tmpDirPath = Utils::CanonicalizePath(tmpDir);
1190	    FUNRET_CHECK_EXPR_ACTION(tmpDirPath.empty(), return MSPROF_DAEMON_ERROR,
1191	        "The tmpDir path: %s does not exist or permission denied.", tmpDirPath.c_str());
1192	    std::ifstream in(tmpDirPath);
1193	    std::ostringstream tmp;
1194	    tmp << in.rdbuf();
1195	    std::string tmpStr = tmp.str();
1196	    OsalUnlink(tmpDirPath.c_str());
1197	    int32_t ret = CheckHostOutString(tmpStr, toolName);
1198	    if (ret != MSPROF_DAEMON_OK) {
1199	        ret = UninitCheckHostSysCmd(tmpProcess); // stop check process.
1200	        if (ret != MSPROF_DAEMON_OK) {
1201	            MSPROF_LOGE("Failed to kill the process.");
1202	        }
1203	        MSPROF_LOGE("The tool %s useless", toolName.c_str());
1204	        return MSPROF_DAEMON_ERROR;
1205	    }
1206	    return ret;
1207	}
