1215	    if (checkToolArray.size() > 0) {
1216	        if (checkToolArray[0].compare(toolName) == 0) {
1217	            MSPROF_LOGI("The returned value is correct.%s", checkToolArray[0].c_str());
1218	            return MSPROF_DAEMON_OK;
1219	        } else {
1220	            MSPROF_LOGE("The return value is incorrect.%s", checkToolArray[0].c_str());
1221	            return MSPROF_DAEMON_ERROR;
1222	        }
1223	    }
1224	    MSPROF_LOGE("The file has no content.");
1225	    return MSPROF_DAEMON_ERROR;
1226	}
