1228	int32_t InputParser::UninitCheckHostSysCmd(const OsalProcess checkProcess) const
1229	{
1230	    if (!(ParamValidation::instance()->CheckHostSysPidIsValid(static_cast<int32_t>(checkProcess)))) {
1231	        return MSPROF_DAEMON_ERROR;
1232	    }
1233	    if (!analysis::dvvp::common::utils::Utils::ProcessIsRuning(checkProcess)) {
1234	        MSPROF_LOGI("Process:%d is not exist", static_cast<int32_t>(checkProcess));
1235	        return MSPROF_DAEMON_OK;
1236	    }
1237	    static const std::string ENV_PATH = "PATH=/usr/bin/:/usr/sbin:/var:/bin";
1238	    std::vector<std::string> envV;
1239	    envV.push_back(ENV_PATH);
1240	    std::vector<std::string> argsV;
1241	    std::string killCmd = "kill -2 " + std::to_string(static_cast<int32_t>(checkProcess));
1242	    argsV.push_back("-c");
1243	    argsV.push_back(killCmd);
1244	    int32_t exitCode = analysis::dvvp::common::utils::VALID_EXIT_CODE;
1245	    static const std::string CMD = "sh";
1246	    OsalProcess tmpProcess = MSVP_PROCESS;
1247	    ExecCmdParams execCmdParams(CMD, true, "");
1248	    int32_t ret = MSPROF_DAEMON_OK;
1249	    for (int32_t i = 0; i < FILE_FIND_REPLAY; i++) {
1250	        if (ParamValidation::instance()->CheckHostSysPidIsValid(static_cast<int32_t>(checkProcess))) {
1251	            ret = analysis::dvvp::common::utils::Utils::ExecCmd(execCmdParams, argsV, envV, exitCode, tmpProcess);
1252	            OsalSleep(20); // If failed stop check process, the delay is 20 ms.
1253	            continue;
1254	        } else {
1255	            break;
1256	        }
1257	    }
1258	    if (checkProcess > 0) {
1259	        bool isExited = false;
1260	        ret = analysis::dvvp::common::utils::Utils::WaitProcess(checkProcess,
1261	                                                                isExited,
1262	                                                                exitCode,
1263	                                                                true);
1264	        if (ret != PROFILING_SUCCESS) {
1265	            ret = MSPROF_DAEMON_ERROR;
1266	            MSPROF_LOGE("Failed to wait process %d, ret=%d",
1267	                        static_cast<int32_t>(checkProcess), ret);
1268	        } else {
1269	            ret = MSPROF_DAEMON_OK;
1270	            MSPROF_LOGI("Process %d exited, exit code=%d",
1271	                        static_cast<int32_t>(checkProcess), exitCode);
1272	        }
1273	    }
1274	    return ret;
1275	}
