1465	int32_t InputParser::CheckAppValid(const struct MsprofCmdInfo &cmdInfo)
1466	{
1467	    if (cmdInfo.args[ARGS_APPLICATION] == nullptr) {
1468	        CmdLog::CmdErrorLog("Argument --application: expected one argument");
1469	        return MSPROF_DAEMON_ERROR;
1470	    }
1471	    std::string appParam = cmdInfo.args[ARGS_APPLICATION];
1472	    if (CheckAppParamValid(appParam) != MSPROF_DAEMON_OK) {
1473	        return MSPROF_DAEMON_ERROR;
1474	    }
1475	    std::string tmpAppParamers;
1476	    size_t index = appParam.find_first_of(" ");
1477	    if (index != std::string::npos) {
1478	        tmpAppParamers = appParam.substr(index + 1);
1479	    }
1480	    std::string cmdPath = appParam.substr(0, index);
1481	    cmdPath = Utils::IdeReplaceWaveWithHomedir(cmdPath);
1482	    params_->app_parameters = tmpAppParamers;
1483	    if (!Utils::IsAppName(cmdPath)) {
1484	        // e.g: bash xx.sh args or python xx.py args or python -m xx args or /usr/bin/python xx.py args
1485	        // set app_dir to './' to set result_dir to current dir when --output not set, and set app to cmd to avoid empty app error in HandleApp, and save all app parameters to app_parameters.
1486	        if (tmpAppParamers.empty()) {
1487	            CmdLog::CmdErrorLog("Argument --application: an interpreter (python/bash/sh) requires a script or module argument");
1488	            return MSPROF_DAEMON_ERROR;
1489	        }
1490	        if (cmdPath.find('/') != std::string::npos) {
1491	            std::string canPath = Utils::CanonicalizePath(cmdPath);
1492	            if (canPath.empty()) {
1493	                CmdLog::CmdErrorLog("Script path(%s) does not exist or permission denied.", cmdPath.c_str());
1494	                return MSPROF_DAEMON_ERROR;
1495	            }
1496	            if (OsalAccess2(canPath.c_str(), OSAL_X_OK) != OSAL_EN_OK) {
1497	                CmdLog::CmdErrorLog("This app(%s) has no executable permission!", canPath.c_str());
1498	                return MSPROF_DAEMON_ERROR;
1499	            }
1500	            cmdPath = canPath;
1501	        }
1502	        params_->cmdPath = cmdPath;
1503	        params_->app_dir = Utils::GetCwdString();
1504	        params_->app = Utils::BaseName(cmdPath);
1505	        return MSPROF_DAEMON_OK;
1506	    }
1507	    // e.g: ./main args
1508	    // set app_dir to cmdPath dir to set result_dir to app dir when --output not set, and set app to cmdPath base name to avoid empty app error in HandleApp, and save all app parameters to app_parameters.
1509	    return CheckUserCmdValid(cmdPath);
1510	}
