1564	int32_t InputParser::CheckDynProfValid(struct MsprofCmdInfo &cmdInfo) const
1565	{
1566	    const auto app = params_->app;
1567	    const auto dynamic = params_->dynamic;
1568	    const auto pid = params_->pid;
1569	    MSPROF_LOGD("app:%s, dynamic:%s, pid:%s", app.c_str(), dynamic.c_str(), pid.c_str());
1570	    // --dynamic empty
1571	    if (dynamic.empty() || dynamic == OFF) {
1572	        // --dynamic empty && --pid not empty
1573	        if (!pid.empty()) {
1574	            CmdLog::CmdErrorLog("Argument --dynamic=off, but --pid is set.");
1575	            MSPROF_LOGE("Argument --dynamic=off, but --pid is set.");
1576	            return MSPROF_DAEMON_ERROR;
1577	        } else {
1578	            return MSPROF_DAEMON_OK;
1579	        }
1580	    }
1581	    // --pid and --application is both empty
1582	    if (app.empty() && pid.empty()) {
1583	        CmdLog::CmdErrorLog("Argument --dynamic=on, but --application/--pid is all empty.");
1584	        MSPROF_LOGE("Argument --dynamic=on, but --application/--pid is all empty.");
1585	        return MSPROF_DAEMON_ERROR;
1586	    }
1587	    // --pid and --application is both non-empty
1588	    if (!app.empty() && !pid.empty()) {
1589	        CmdLog::CmdErrorLog("Argument --dynamic=on, can not set --application/--pid at the same time.");
1590	        MSPROF_LOGE("Argument --dynamic=on, can not set --application/--pid at the same time.");
1591	        return MSPROF_DAEMON_ERROR;
1592	    }
1593	    // Check whether the switch parameter conflicts with the dynamic parameter.
1594	    FUNRET_CHECK_EXPR_ACTION(CheckDynConflict(cmdInfo), return MSPROF_DAEMON_ERROR,
1595	        "Failed to check the parameter conflict about dynamic mode.");
1596	
1597	    // --pid is non-empty, save pid to DynProfCliMgr
1598	    std::vector<int32_t> pids;
1599	    if (!pid.empty()) {
1600	        if (!CheckDynaProfPidValid(pid, pids)) {
1601	            return MSPROF_DAEMON_ERROR;
1602	        }
1603	        DynProfCliMgr::instance()->SetKeyPid(pids);
1604	    } else { // app mode, set msprofbin pid
1605	        DynProfCliMgr::instance()->SetAppMode();
1606	        pids.push_back(Utils::GetPid());
1607	        DynProfCliMgr::instance()->SetKeyPid(pids);
1608	    }
1609	    DynProfCliMgr::instance()->EnableDynProfCli();
1610	    return MSPROF_DAEMON_OK;
1611	}
1612	
1613	bool InputParser::CheckDynaProfPidValid(const std::string &pid, std::vector<int32_t> &validPids) const
1614	{
1615	    int32_t pidInt = 0;
1616	    std::vector<std::string> nonNumPidVec;
1617	    std::vector<std::string> invalidPidVec;
1618	    auto pidStrVec = Utils::Split(pid, false, "", ",");
1619	    for (auto &pidStr : pidStrVec) {
1620	        if (pidStr.empty()) {
1621	            continue;
1622	        }
1623	        if (!Utils::StrToInt32(pidInt, pidStr)) {
1624	            nonNumPidVec.push_back(pidStr);
1625	        } else if (!ParamValidation::instance()->CheckDynaPidIsValid(pidInt)) {
1626	            invalidPidVec.push_back(pidStr);
1627	        } else {
1628	            validPids.push_back(pidInt);
1629	        }
1630	    }
1631	    UtilsStringBuilder<std::string> builder;
1632	    if (!nonNumPidVec.empty()) {
1633	        CmdLog::CmdErrorLog("Argument --pid: invalid non-numeric pid value: %s, stop profiling.",
1634	            builder.Join(nonNumPidVec, ",").c_str());
1635	        return false;
1636	    }
1637	    if (validPids.empty()) {
1638	        CmdLog::CmdErrorLog("Argument --pid: no valid pid values, stop profiling.");
1639	        return false;
1640	    }
1641	    if (!invalidPidVec.empty()) {
1642	        CmdLog::CmdWarningLog("Argument --pid: invalid pid value: %s, "
1643	                              "will not collect profiling data for these process.",
1644	            builder.Join(invalidPidVec, ",").c_str());
1645	    }
1646	    return true;
1647	}
