78	int32_t RunningMode::CheckForbiddenParams() const
79	{
80	    if (params_ == nullptr || params_->usedParams.empty()) {
81	        return PROFILING_FAILED;
82	    }
83	    std::set<int32_t> usedForbiddenParams;
84	    set_intersection(params_->usedParams.begin(), params_->usedParams.end(), blackSet_.begin(), blackSet_.end(),
85	                     inserter(usedForbiddenParams, usedForbiddenParams.begin()));
86	    if (!usedForbiddenParams.empty()) {
87	        std::string forbiddenParamsStr = ConvertParamsSetToString(usedForbiddenParams);
88	        CmdLog::CmdErrorLog("The argument %s is forbidden when --%s is not empty", forbiddenParamsStr.c_str(),
89	                            preCheckParams_.c_str());
90	        return PROFILING_FAILED;
91	    }
92	    return PROFILING_SUCCESS;
93	}
