145	int32_t RunningMode::GetOutputDirInfoFromRecord()
146	{
147	    if (!jobResultDir_.empty()) {
148	        MSPROF_LOGW("Unable to get output info from record, exist output info before.");
149	        return PROFILING_FAILED;
150	    }
151	    std::string baseDir;
152	    std::ifstream fin;
153	    std::string resultDirTmp = params_->result_dir;
154	    Utils::EnsureEndsInSlash(resultDirTmp);
155	    std::string pidStr = std::to_string(Utils::GetPid());
156	    std::string recordFile = pidStr + MSVP_UNDERLINE + OUTPUT_RECORD;
157	    std::string outPut = resultDirTmp + recordFile;
158	    int64_t fileSize = Utils::GetFileSize(outPut);
159	    if (fileSize > MSVP_SMALL_FILE_MAX_LEN || fileSize <= 0) {
160	        MSPROF_LOGW("File size is invalid. fileName:%s, size:%lld bytes.", recordFile.c_str(), fileSize);
161	        return PROFILING_FAILED;
162	    }
163	    outPut = Utils::CanonicalizePath(outPut);
164	    FUNRET_CHECK_EXPR_ACTION(outPut.empty(), return PROFILING_FAILED,
165	                             "The output path: %s does not exist or permission denied.", outPut.c_str());
166	    fin.open(outPut, std::ifstream::in);
167	    if (fin.is_open()) {
168	        while (getline(fin, baseDir)) {
169	            jobResultDirList_.insert(resultDirTmp + baseDir);
170	        }
171	        fin.close();
172	        RemoveRecordFile(outPut);
173	        return PROFILING_SUCCESS;
174	    } else {
175	        char errBuf[MAX_ERR_STRING_LEN + 1] = { 0 };
176	        MSPROF_LOGE("Open file failed, fileName:%s, error: %s", Utils::BaseName(recordFile).c_str(),
177	                    OsalGetErrorFormatMessage(OsalGetErrorCode(), errBuf, MAX_ERR_STRING_LEN));
178	        return PROFILING_FAILED;
179	    }
180	}
