222	int32_t RunningMode::StartAnalyzeTask()
223	{
224	    if (isQuit_) {
225	        MSPROF_LOGE("Start analyze task error, msprofbin has quited.");
226	        return PROFILING_FAILED;
227	    }
228	
229	    if (taskPid_ != MSVP_PROCESS) {
230	        MSPROF_LOGE("Start analyze task error, process %d is running,"
231	                    "only one child process can run at the same time.",
232	                    static_cast<int32_t>(taskPid_));
233	        return PROFILING_FAILED;
234	    }
235	
236	    if (jobResultDir_.empty() || analysisPath_.empty()) {
237	        MSPROF_LOGE("Start analyze task error, get output dir and msprof.py script failed.");
238	        return PROFILING_FAILED;
239	    }
240	
241	    CmdLog::CmdInfoLog("Start analyze data in %s.", Utils::BaseName(jobResultDir_).c_str());
242	    taskName_ = "Analyze";
243	    std::string cmd = params_->pythonPath;
244	    ExecCmdParams execCmdParams(cmd, true, "");
245	    std::vector<std::string> envsV;
246	    int32_t exitCode = INVALID_EXIT_CODE;
247	    SetEnvList(envsV);
248	    std::vector<std::string> argsV = { analysisPath_, "analyze", "-dir=" + jobResultDir_,
249	                                       "-r=" + params_->analyzeRuleSwitch };
250	    if (params_->clearSwitch == "on") {
251	        argsV.push_back("--clear");
252	    }
253	    if (params_->exportType == "db") {
254	        argsV.push_back("--type=db");
255	    }
256	
257	    int32_t ret = Utils::ExecCmd(execCmdParams, argsV, envsV, exitCode, taskPid_);
258	    if (ret == PROFILING_FAILED) {
259	        MSPROF_LOGE("Failed to launch analyze task, data path: %s", Utils::BaseName(jobResultDir_).c_str());
260	        return PROFILING_FAILED;
261	    }
262	
263	    ret = WaitRunningProcess(taskName_);
264	    if (ret != PROFILING_SUCCESS) {
265	        MSPROF_LOGE("Failed to wait analyze process %d to exit, ret=%d", static_cast<int32_t>(taskPid_), ret);
266	        return PROFILING_FAILED;
267	    }
268	
269	    taskPid_ = MSVP_PROCESS;
270	    exitCode = INVALID_EXIT_CODE;
271	    CmdLog::CmdInfoLog("Analyze all data in %s done.", Utils::BaseName(jobResultDir_).c_str());
272	    return PROFILING_SUCCESS;
273	}
