485	int32_t RunningMode::WaitRunningProcess(std::string processUsage)
486	{
487	    if (taskPid_ == MSVP_PROCESS) {
488	        MSPROF_LOGE("[WaitRunningProcess] Invalid task pid.");
489	        return PROFILING_FAILED;
490	    }
491	    bool isExited = false;
492	    int32_t exitCode = 0;
493	    int32_t ret = PROFILING_SUCCESS;
494	    static const int32_t SLEEP_INTEVAL_US = 1000000;
495	    const int32_t lltExitCode = 256;
496	
497	    for (;;) {
498	        ret = analysis::dvvp::common::utils::Utils::WaitProcess(taskPid_, isExited, exitCode, false);
499	        if (ret != PROFILING_SUCCESS) {
500	            MSPROF_LOGE("Failed to wait %s process %d to exit, ret=%d", processUsage.c_str(),
501	                        static_cast<int32_t>(taskPid_), ret);
502	            return ret;
503	        }
504	        if (isExited) {
505	            MSPROF_EVENT("%s process %d exited, exit code:%d", processUsage.c_str(), static_cast<int32_t>(taskPid_),
506	                         exitCode);
507	            if (exitCode != 0 && !isQuit_) {
508	                MSPROF_LOGW("An exception has occurred in process %s, return code: %s.", processUsage.c_str(),
509	                            strerror(exitCode));
510	                CmdLog::CmdWarningLog("An exception has occurred in process %s, return code: %s.",
511	                            processUsage.c_str(), strerror(exitCode));
512	            }
513	            if (exitCode == lltExitCode) {
514	                return PROFILING_FAILED;
515	            }
516	            return PROFILING_SUCCESS;
517	        }
518	        if (isQuit_) {
519	            StopNoWait();
520	        }
521	        analysis::dvvp::common::utils::Utils::UsleepInterupt(SLEEP_INTEVAL_US);
522	    }
523	}
