535	int32_t RunningMode::CheckAnalysisEnv()
536	{
537	    if (isQuit_) {
538	        MSPROF_LOGE("Check Analysis env failed, msprofbin has quited");
539	        return PROFILING_FAILED;
540	    }
541	    if (Platform::instance()->RunSocSide()) {
542	        CmdLog::CmdWarningLog("Not in host side, analysis is not supported");
543	        return PROFILING_FAILED;
544	    }
545	    if (params_->pythonPath.empty()) {
546	        const std::string PYTHON_CMD{ "python3" };
547	        params_->pythonPath = PYTHON_CMD;
548	    }
549	    // check analysis scripts
550	    std::string absolutePath = Utils::GetSelfPath();
551	    std::string dirName = Utils::DirName(absolutePath);
552	    std::string msprofToolsPath;
553	    std::string binPath;
554	    if (Utils::SplitPath(dirName, msprofToolsPath, binPath) != PROFILING_SUCCESS) {
555	        CmdLog::CmdWarningLog("Get profiler path failed.");
556	        return PROFILING_FAILED;
557	    }
558	    Utils::EnsureEndsInSlash(msprofToolsPath);
559	    const std::string ANALYSIS_SCRIPT_PATH{ "profiler_tool/analysis/msprof/msprof.py" };
560	    analysisPath_ = msprofToolsPath + ANALYSIS_SCRIPT_PATH;
