574	int32_t RunningMode::HandleProfilingParams() const
575	{
576	    if (params_ == nullptr) {
577	        MSPROF_LOGE("ProfileParams is not valid!");
578	        return PROFILING_FAILED;
579	    }
580	    if (params_->devices.compare("all") == 0) {
581	        params_->devices = DrvGetDevIdsStr();
582	    }
583	    std::string aiCoreMetrics;
584	    std::string aiVectMetrics;
585	    if (ConfigManager::instance()->GetPlatformType() == PlatformType::MINI_V3_TYPE ||
586	        ConfigManager::instance()->GetPlatformType() == PlatformType::CHIP_MDC_MINI_V3 ||
587	        ConfigManager::instance()->GetPlatformType() == PlatformType::CHIP_TINY_V1 ||
588	        ConfigManager::instance()->GetPlatformType() == PlatformType::CHIP_MDC_LITE) {
589	        aiCoreMetrics = params_->ai_core_metrics.empty() ? PIPE_EXECUTION_UTILIZATION : params_->ai_core_metrics;
590	    } else {
591	        aiCoreMetrics = params_->ai_core_metrics.empty() ? PIPE_UTILIZATION : params_->ai_core_metrics;
592	    }
593	    if (ConfigManager::instance()->GetPlatformType() == PlatformType::MDC_TYPE) {
594	        aiVectMetrics = params_->aiv_metrics.empty() ? PIPE_UTILIZATION : params_->aiv_metrics;
595	    } else {
596	        aiVectMetrics = aiCoreMetrics;
597	    }
598	    ConfigManager::instance()->GetVersionSpecificMetrics(aiCoreMetrics);
599	    int32_t ret = Platform::instance()->GetAicoreEvents(aiCoreMetrics, params_->ai_core_profiling_events);
600	    if (ret != PROFILING_SUCCESS) {
601	        MSPROF_LOGE("Failed to get AI Core PMU events for metrics [%s] on current platform.", aiCoreMetrics.c_str());
602	        return PROFILING_FAILED;
603	    }
604	    if (params_->ntsMetrics == PIPE_UTILIZATION) {
605	        ret = Platform::instance()->GetAicoreEvents(PIPE_UTILIZATION_EXCT, params_->ntsPmuEvents);
606	        if (ret != PROFILING_SUCCESS) {
607	            MSPROF_LOGE("Failed to get NTS PMU events for metrics [%s] on current platform.",
608	                params_->ntsMetrics.c_str());
609	            return PROFILING_FAILED;
610	        }
611	    }
612	    params_->ai_core_metrics = aiCoreMetrics;
613	    ret = Platform::instance()->GetAicoreEvents(aiVectMetrics, params_->aiv_profiling_events);
614	    params_->aiv_metrics = aiVectMetrics;
615	    Platform::instance()->L2CacheAdaptor(params_->npuEvents, params_->l2CacheTaskProfiling,
616	        params_->l2CacheTaskProfilingEvents);
617	    Analysis::Dvvp::Msprof::MsprofParamsAdapter::instance()->GenerateLlcEvents(params_);
618	    params_->msprofBinPid = Utils::GetPid();
619	    return MsprofParamsAdapter::instance()->UpdateParams(params_);
620	}
