656	int32_t AppMode::RunModeTasks()
657	{
658	    if (params_ == nullptr) {
659	        MSPROF_LOGE("[App Mode] Invalid params!");
660	        return PROFILING_FAILED;
661	    }
662	    SetDefaultParams();
663	    if (DynProfCliMgr::instance()->IsDynProfCliEnable()) {
664	        return StartAppTaskForDynProf();
665	    }
666	
667	    auto startTime = std::chrono::high_resolution_clock::now();
668	    if (StartAppTask() != PROFILING_SUCCESS) {
669	        MSPROF_LOGE("[App Mode] Run application task failed.");
670	        return PROFILING_FAILED;
671	    }
672	    auto endTime = std::chrono::high_resolution_clock::now();
673	    UpdateOutputDirInfo();
674	
675	    if (isQuit_) {
676	        isQuit_ = false;
677	        MSPROF_LOGI("reset isQuit_=false to analsys data");
678	    }
679	
680	    if (jobResultDirList_.empty()) {
681	        auto duration = std::chrono::duration_cast<std::chrono::seconds>(endTime - startTime);
682	        if (!params_->delayTime.empty() && static_cast<uint64_t>(duration.count()) <= std::stoull(params_->delayTime)) {
683	            MSPROF_LOGW("[App Mode] Before delay time, the app process has exited.");
684	            return PROFILING_SUCCESS;
685	        }
686	        MSPROF_LOGE("[App Mode] Failed to find profiling data");
687	        CmdLog::CmdErrorLog("Failed to find profiling data,"
688	                            " please check that the application executes AI-related business,"
689	                            " or ensure that aclInit/GEInitialize is invoked in the application");
690	        return PROFILING_FAILED;
691	    }
692	
693	    if (CheckAnalysisEnv() != PROFILING_SUCCESS) {
694	        MSPROF_LOGW("[App Mode] Analysis environment is not OK, auto parse will not start.");
695	        return PROFILING_SUCCESS;
696	    }
697	
698	    std::set<std::string>::iterator iter;
699	    for (iter = jobResultDirList_.begin(); iter != jobResultDirList_.end(); ++iter) {
700	        jobResultDir_ = *iter;
701	        if (StartExportTask() != PROFILING_SUCCESS) {
702	            MSPROF_LOGW("[App Mode] The export task did not complete successfully.");
703	            return PROFILING_SUCCESS;
704	        }
705	        if (StartQueryTask() != PROFILING_SUCCESS) {
706	            MSPROF_LOGW("[App Mode] The query task did not complete successfully.");
707	            return PROFILING_SUCCESS;
708	        }
709	    }
710	    return PROFILING_SUCCESS;
711	}
