743	int32_t AppMode::StartAppTaskForDynProf()
744	{
745	    if (isQuit_) {
746	        MSPROF_LOGE("Failed to launch app, msprofbin has quited");
747	        return PROFILING_FAILED;
748	    }
749	    if (DynProfCliMgr::instance()->IsAppMode()) {
750	        if (analysis::dvvp::app::Application::LaunchApp(params_, taskPid_) != PROFILING_SUCCESS) {
751	            MSPROF_LOGE("Dynamic profiling failed to launch application.");
752	            return PROFILING_FAILED;
753	        }
754	        // wait server start
755	        const int32_t sleepUs = 2 * 1000 * 1000;  // 2s
756	        Utils::UsleepInterupt(sleepUs);
757	    }
758	
759	    if (DynProfCliMgr::instance()->StartDynProfCli(params_->ToString()) != PROFILING_SUCCESS) {
760	        MSPROF_LOGE("Dynamic profiling start client thread fail.");
761	        // 关闭app
762	        StopRunningTasks();
763	        return PROFILING_FAILED;
764	    }
765	
766	    MSPROF_LOGI("Dynamic profiling start client success.");
767	    DynProfCliMgr::instance()->WaitQuit();
768	
769	    taskName_ = "app";
770	    if (DynProfCliMgr::instance()->IsAppMode() && !isQuit_) {
771	        CmdLog::CmdInfoLog("waiting for app process exit......");
772	        // wait app exit
773	        auto ret = WaitRunningProcess(taskName_);
774	        if (ret != PROFILING_SUCCESS) {
775	            MSPROF_LOGE("Failed to wait process %d to exit, ret=%d", static_cast<int32_t>(taskPid_), ret);
776	            return PROFILING_FAILED;
777	        }
778	    }
779	    taskPid_ = MSVP_PROCESS;
780	    return PROFILING_SUCCESS;
781	}
