783	int32_t AppMode::StartAppTask(bool needWait)
784	{
785	    if (isQuit_) {
786	        MSPROF_LOGE("Failed to launch app, msprofbin has quited");
787	        return PROFILING_FAILED;
788	    }
789	    int32_t ret = analysis::dvvp::app::Application::LaunchApp(params_, taskPid_);
790	    if (ret == PROFILING_FAILED) {
