799	            MSPROF_LOGE("Failed to wait process %d to exit, ret=%d", static_cast<int32_t>(taskPid_), ret);
800	            return PROFILING_FAILED;
801	        }
802	    }
803	    taskPid_ = MSVP_PROCESS;
804	    return PROFILING_SUCCESS;
