855	int32_t SystemMode::CheckIfDeviceOnline() const
856	{
857	    if (params_->devices.compare("all") == 0) {
858	        return PROFILING_SUCCESS;
859	    }
860	    auto devIds = Utils::Split(params_->devices, false, "", ",");
861	    const int32_t numDevices = DrvGetDevNum();
862	    if (numDevices <= 0) {
863	        CmdLog::CmdErrorLog("Get dev's num %d failed", numDevices);
864	        return PROFILING_FAILED;
865	    }
866	    std::vector<int32_t> devices;
867	    int32_t ret = DrvGetDevIds(numDevices, devices);
868	    if (ret != PROFILING_SUCCESS) {
869	        CmdLog::CmdErrorLog("Get dev's id failed");
870	        return PROFILING_FAILED;
871	    }
872	    UtilsStringBuilder<int32_t> builder;
873	    builder.Join(devices, ",");
874	    std::set<std::string> validIds;
875	    std::vector<std::string> invalidIds;
876	    for (auto devId : devIds) {
877	        if (!Utils::CheckStringIsNonNegativeIntNum(devId)) {
878	            CmdLog::CmdErrorLog("The device (%s) is not valid, please check it!", devId.c_str());
879	            return PROFILING_FAILED;
880	        }
881	        int32_t devIdInt = 0;
882	        FUNRET_CHECK_EXPR_ACTION(!Utils::StrToInt32(devIdInt, devId), return PROFILING_FAILED, 
883	            "devId %s is invalid", devId.c_str());
884	        auto it = find(devices.begin(), devices.end(), devIdInt);
885	        if (it == devices.end()) {
886	            invalidIds.push_back(devId);
887	        } else {
888	            validIds.insert(devId);
889	        }
890	    }
891	    UtilsStringBuilder<std::string> strBuilder;
892	    if (!invalidIds.empty()) {
893	        CmdLog::CmdWarningLog("The following devices(%s) are offline and will not collect.",
894	                              strBuilder.Join(invalidIds, ",").c_str());
895	    }
896	    if (validIds.empty()) {
897	        CmdLog::CmdErrorLog("Argument --sys-devices is invalid,"
898	                            "Please enter a valid --sys-devices value.");
899	        return PROFILING_FAILED;
900	    }
901	    std::vector<std::string> validIdList;
902	    validIdList.assign(validIds.begin(), validIds.end());
903	    params_->devices = strBuilder.Join(validIdList, ",");
904	    return PROFILING_SUCCESS;
905	}
