920	bool SystemMode::DataWillBeCollected() const
921	{
922	    if (params_ == nullptr || params_->usedParams.empty()) {
923	        return false;
924	    }
925	    std::set<int32_t> necessaryParams = neccessarySet_;
926	    necessaryParams.insert(ARGS_OUTPUT);
927	    std::set<int32_t> unneccessaryParams;
928	    set_difference(params_->usedParams.begin(), params_->usedParams.end(), necessaryParams.begin(), necessaryParams.end(),
929	                   inserter(unneccessaryParams, unneccessaryParams.begin()));
930	    set_intersection(params_->usedParams.begin(), params_->usedParams.end(), unneccessaryParams.begin(),
931	                     unneccessaryParams.end(), inserter(unneccessaryParams, unneccessaryParams.begin()));
932	    if (unneccessaryParams.size() == 1 && *(unneccessaryParams.begin()) == ARGS_SYS_DEVICES) {
933	        CmdLog::CmdWarningLog("No collection data type is specified, profiling will not start");
934	        return false;
935	    }
936	    return true;
