1038	int32_t SystemMode::RecordOutPut() const
1039	{
1040	    std::string pidStr = std::to_string(Utils::GetPid());
1041	    std::string recordFile = pidStr + MSVP_UNDERLINE + OUTPUT_RECORD;
1042	    std::string absolutePath = params_->result_dir + MSVP_SLASH + recordFile;
1043	    std::ofstream file;
1044	    file.open(absolutePath, std::ios::out | std::ios::app);
1045	    if (!file.is_open()) {
1046	        MSPROF_LOGE("Failed to open %s", Utils::BaseName(recordFile).c_str());
1047	        return PROFILING_FAILED;
