1049	    if (OsalChmod(absolutePath.c_str(), FILE_MODE) != OSAL_EN_OK) {
1050	        file.close();
1051	        MSPROF_LOGE("Failed to change file mode for %s", absolutePath.c_str());
1052	        return PROFILING_FAILED;
1053	    }
1054	    file << baseDir_ << std::endl << std::flush;
