1090	        MSPROF_LOGE("DeviceTask init failed, deviceId:%u", deviceId);
1091	        return PROFILING_FAILED;
1092	    }
1093	    ret = task->Start();
1094	    if (ret != PROFILING_SUCCESS) {
1095	        MSPROF_LOGE("DeviceTask start failed, deviceId:%u", deviceId);
1096	        return PROFILING_FAILED;
1097	    }
1098	    taskMap_[params->job_id] = task;
