1139	void SystemMode::StopTask()
1140	{
1141	    if (taskList_.empty()) {
1142	        return;
1143	    }
1144	    for (auto task = taskList_.end() - 1; task >= taskList_.begin(); task--) {
1145	        (*task)->Stop();
1146	        (*task)->Wait();
1147	    }
1148	    taskList_.clear();
1149	    taskMap_.clear();
