1152	int32_t SystemMode::WaitSysTask() const
1153	{
1154	    uint32_t times = 0;
1155	    uint32_t cycles = 0;
1156	
1157	    if (params_->profiling_period > 0) {
1158	        cycles = static_cast<uint32_t>(params_->profiling_period * US_TO_SECOND_TIMES(PROCESS_WAIT_TIME));
1159	    }
1160	    while ((times < cycles) && (!isQuit_)) {
1161	        analysis::dvvp::common::utils::Utils::UsleepInterupt(PROCESS_WAIT_TIME);
1162	        times++;
1163	    }
1164	    return PROFILING_SUCCESS;
1165	}
