1317	    }
1318	
1319	    if (data.empty() || dataLen <= 0) {
1320	        MSPROF_LOGE("Failed to open %s", Utils::BaseName(absolutePath).c_str());
1321	        return PROFILING_FAILED;
1322	    }
1323	    file.open(absolutePath, std::ios::out | std::ios::trunc);
