1330	        MSPROF_LOGE("Failed to change file mode for %s", absolutePath.c_str());
1331	        return PROFILING_FAILED;
1332	    }
1333	    file.write(data.c_str(), dataLen);
1334	    file.flush();
1335	    file.close();
1336	
1337	    if (!(CreateDoneFile(absolutePath + ".done", std::to_string(dataLen)))) {
