1397	int32_t SystemMode::StartSysTask()
1398	{
1399	    std::vector<std::string> devices = Utils::Split(params_->devices, false, "", ",");
1400	    params_->PrintAllFields();
1401	    baseDir_ = Utils::CreateProfDir(0);
1402	    if (RecordOutPut() != PROFILING_SUCCESS) {
1403	        MSPROF_LOGW("Unable to record output dir: %s", Utils::BaseName(baseDir_).c_str());
1404	    }
1405	    if (params_->IsHostProfiling()) {
1406	        if (StartHostJobs() != PROFILING_SUCCESS) {
1407	            return PROFILING_FAILED;
1408	        }
1409	    }
1410	    for (auto device : devices) {
1411	        auto ret = StartDeviceJobs(device);
1412	        if (ret != PROFILING_SUCCESS) {
1413	            return ret;
1414	        }
1415	    }
1416	    int32_t waitRet = WaitSysTask();
1417	    if (waitRet != PROFILING_SUCCESS) {
1418	        MSPROF_LOGE("WaitSysTask failed");
1419	        return PROFILING_FAILED;
1420	    }
1421	    StopTask();
1422	    return waitRet;
1423	}
