RunningMode::RunningMode(std::string preCheckParams, std::string modeName, SHARED_PTR_ALIA<ProfileParams> params)
    : isQuit_(false),
      modeName_(modeName),
      taskPid_(MSVP_PROCESS),
      preCheckParams_(preCheckParams),
      blackSet_(),
      whiteSet_(),
      neccessarySet_(),
      params_(params),
      taskMap_()
{
