155	int32_t MsprofTask::CreateCollectionTimeInfo(std::string collectionTime, bool isStartTime)
156	{
157	    MSPROF_LOGI("collectionTime:%s us, isStartTime:%d", collectionTime.c_str(), isStartTime);
158	    // time to unix
159	    const int32_t timeUs = 1000000;
160	    SHARED_PTR_ALIA<CollectionStartEndTime> timeInfo = nullptr;
161	    MSVP_MAKE_SHARED0(timeInfo, CollectionStartEndTime, return PROFILING_FAILED);
162	    if (!isStartTime) {
163	        timeInfo->collectionTimeEnd = collectionTime;
164	        timeInfo->collectionDateEnd = Utils::TimestampToTime(collectionTime, timeUs);
165	    } else {
166	        timeInfo->collectionTimeBegin = collectionTime;
167	        timeInfo->collectionDateBegin = Utils::TimestampToTime(collectionTime, timeUs);
168	    }
169	    timeInfo->clockMonotonicRaw = std::to_string(Utils::GetClockMonotonicRaw());
170	    std::string content;
171	    try {
172	        content = EncodeTimeInfoJson(timeInfo);
173	    } catch (const std::runtime_error &error) {
174	        return PROFILING_FAILED;
175	    }
176	    MSPROF_LOGI("CreateCollectionTimeInfo, content:%s", content.c_str());
177	    SHARED_PTR_ALIA<analysis::dvvp::message::JobContext> jobCtx = nullptr;
178	    MSVP_MAKE_SHARED0(jobCtx, analysis::dvvp::message::JobContext, return PROFILING_FAILED);
