186	    int32_t ret = analysis::dvvp::transport::UploaderMgr::instance()->UploadCtrlFileData(params_->job_id, content,
187	                                                                                     fileDataParams, jobCtx);
188	    if (ret != PROFILING_SUCCESS) {
189	        MSPROF_LOGE("Failed to upload data for %s", fileName.c_str());
190	        return PROFILING_FAILED;
191	    }
192	    return PROFILING_SUCCESS;
